// Build table definitions as compact tuples: [tableName, [fields]]
// Each field = [dbName, dbType, comment]
// Audit fields (created_at/updated_at/creator/updater/deleted_at) and deleted are in BaseEntity -> skipped
// 'id' PK is also generated by template (skipped here)
const SKIP_FIELDS = new Set([
  'id',
  'created_at', 'updated_at', 'creator', 'updater', 'deleted_at', 'deleted',
]);

// Helper: filter rows -> keep business fields (skip audit + id), map types
function f(rows) {
  return rows
    .filter(([name]) => !SKIP_FIELDS.has(name))
    .map(([name, type, comment]) => ({ name, type: mapTypeSafe(type), comment }));
}
// inline mapType (since not exported directly here)
const { mapType } = require('./gen-modules.js');
function mapTypeSafe(t) { return mapType(t); }

